import { useEffect, useState } from "react";

export default function CustomCursor() {
  const [position, setPosition] = useState({
    x: 0,
    y: 0,
  });

  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const handleMouseMove = (event: MouseEvent) => {
      setPosition({
        x: event.clientX,
        y: event.clientY,
      });

      setVisible(true);
    };

    const handleMouseLeave = () => {
      setVisible(false);
    };

    window.addEventListener("mousemove", handleMouseMove);
    document.documentElement.addEventListener(
      "mouseleave",
      handleMouseLeave
    );

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      document.documentElement.removeEventListener(
        "mouseleave",
        handleMouseLeave
      );
    };
  }, []);

  return (
    <div
      className={`pointer-events-none fixed left-0 top-0 z-[9999] hidden md:block ${
        visible ? "opacity-100" : "opacity-0"
      }`}
      style={{
        transform: `translate3d(${position.x}px, ${position.y}px, 0)`,
        transition: "opacity 150ms ease",
      }}
    >
      {/* Arrow */}
      <svg
        width="38"
        height="46"
        viewBox="0 0 38 46"
        fill="none"
        className="absolute left-0 top-0"
      >
        <path
          d="M3 2L35 20L19 23L14 42L3 2Z"
          fill="white"
          stroke="black"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
      </svg>

      {/* Designer label */}
      <div
        className="absolute left-[43px] top-[8px] whitespace-nowrap rounded-[18px] bg-white px-5 py-3 text-[22px] font-semibold leading-none tracking-[-0.03em] text-neutral-950 shadow-[0_4px_20px_rgba(0,0,0,0.08)]"
      >
        Designer
      </div>
    </div>
  );
}
